create table public.kappy_team_links(team_id uuid primary key references public.kappy_teams(id) on delete cascade, token uuid not null unique default gen_random_uuid());
create table public.kappy_join_requests(team_id uuid not null references public.kappy_teams(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,display_name text not null check(length(display_name) between 1 and 60),status text not null default 'pending' check(status in ('pending','approved','declined')),primary key(team_id,user_id));
alter table public.kappy_team_links enable row level security;
alter table public.kappy_join_requests enable row level security;
revoke all on public.kappy_team_links,public.kappy_join_requests from anon,authenticated;
grant select on public.kappy_team_links,public.kappy_join_requests to authenticated;
create policy links_admin on public.kappy_team_links for select to authenticated using(kappy_private.is_admin(team_id));
create policy requests_read on public.kappy_join_requests for select to authenticated using(user_id=auth.uid() or kappy_private.is_admin(team_id));
create function public.kappy_team_link(p_team uuid,p_rotate boolean default false) returns uuid language plpgsql security definer set search_path='' as $$ declare v uuid; begin if auth.uid() is null or not kappy_private.is_admin(p_team) then raise exception 'Admin required'; end if; insert into public.kappy_team_links(team_id) values(p_team) on conflict(team_id) do nothing; if p_rotate then update public.kappy_team_links set token=gen_random_uuid() where team_id=p_team; end if; select token into v from public.kappy_team_links where team_id=p_team; return v; end $$;
create function public.kappy_request_join(p_token uuid,p_name text) returns text language plpgsql security definer set search_path='' as $$ declare t uuid; s text; begin if auth.uid() is null then raise exception 'Sign in first'; end if; select team_id into t from public.kappy_team_links where token=p_token; if t is null then raise exception 'Invalid or replaced invitation'; end if; if kappy_private.is_member(t) then return 'approved'; end if; insert into public.kappy_join_requests(team_id,user_id,display_name) values(t,auth.uid(),trim(p_name)) on conflict do nothing; if found then insert into public.kappy_notifications(team_id,recipient_id,kind,title,body) select t,user_id,'join_request','New membership request','Open Team to review.' from public.kappy_members where team_id=t and role='admin'; end if; select status into s from public.kappy_join_requests where team_id=t and user_id=auth.uid(); return s; end $$;
create function public.kappy_review_join(p_team uuid,p_user uuid,p_approve boolean,p_role text default 'caregiver') returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or not kappy_private.is_admin(p_team) then raise exception 'Admin required'; end if; if p_role not in ('caregiver','family','admin') then raise exception 'Invalid role'; end if; update public.kappy_join_requests set status=case when p_approve then 'approved' else 'declined' end where team_id=p_team and user_id=p_user and status='pending'; if not found then raise exception 'No pending request'; end if; if p_approve then insert into public.kappy_members(team_id,user_id,role) values(p_team,p_user,p_role) on conflict do nothing; end if; end $$;
alter table public.kappy_notifications drop constraint kappy_notifications_kind_check;
alter table public.kappy_notifications add constraint kappy_notifications_kind_check check(kind in ('schedule_request','timesheet_submitted','timesheet_reminder','schedule_decision','chat_message','join_request'));
revoke all on function public.kappy_team_link(uuid,boolean),public.kappy_request_join(uuid,text),public.kappy_review_join(uuid,uuid,boolean,text) from public,anon;
grant execute on function public.kappy_team_link(uuid,boolean),public.kappy_request_join(uuid,text),public.kappy_review_join(uuid,uuid,boolean,text) to authenticated;